using System.IO.Compression;
using PdfPecker.Rendering.Graphics;

namespace PdfPecker.Rendering.Fonts;

/// <summary>
/// Built-in outlines for the 14 standard PDF fonts and for non-embedded fonts. The glyphs come from the Liberation
/// fonts (metric-compatible with Helvetica, Times and Courier) and DejaVu Sans (Symbol and ZapfDingbats), both under
/// permissive licenses; see THIRD-PARTY-NOTICES.md. The data is generated by tools/FontPackBuilder.
/// </summary>
internal static class StandardFontPack
{
    public const string ResourceName = "PdfPecker.Rendering.Fonts.StandardFonts.bin";

    private static readonly Lazy<Pack> Data = new(Load, LazyThreadSafetyMode.ExecutionAndPublication);

    private sealed class Pack
    {
        public readonly Dictionary<string, int> Names = new(StringComparer.Ordinal);
        public readonly Dictionary<string, PackFace> Faces = new(StringComparer.Ordinal);
    }

    public static int? NameToUnicode(string name) => Data.Value.Names.TryGetValue(name, out int u) ? u : null;

    /// <summary>A face by pack name: Sans, Serif or Mono with optional -Bold, -Italic, -BoldItalic; Symbol; Dingbats.</summary>
    public static PackFace? Face(string name) => Data.Value.Faces.TryGetValue(name, out var f) ? f : null;

    private static Pack Load()
    {
        var pack = new Pack();
        using var stream = typeof(StandardFontPack).Assembly.GetManifestResourceStream(ResourceName);
        if (stream == null) return pack;
        using var z = new DeflateStream(stream, CompressionMode.Decompress);
        using var ms = new MemoryStream();
        z.CopyTo(ms);
        var r = new Reader(ms.ToArray());
        if (r.Byte() != 'P' || r.Byte() != 'P' || r.Byte() != 'F' || r.Byte() != '1') return pack;
        int names = r.VarInt();
        for (int i = 0; i < names; i++)
        {
            string n = r.Str();
            pack.Names[n] = r.VarInt();
        }
        int faces = r.VarInt();
        for (int i = 0; i < faces; i++)
        {
            var f = PackFace.Read(r);
            pack.Faces[f.Name] = f;
        }
        return pack;
    }

    internal sealed class Reader
    {
        public readonly byte[] D;
        public int Pos;
        public Reader(byte[] d) => D = d;
        public byte Byte() => D[Pos++];

        public int VarInt()
        {
            int v = 0, shift = 0;
            while (true)
            {
                byte b = D[Pos++];
                v |= (b & 0x7F) << shift;
                if ((b & 0x80) == 0) return v;
                shift += 7;
            }
        }

        public int ZigZag()
        {
            int v = VarInt();
            return (v >> 1) ^ -(v & 1);
        }

        public string Str()
        {
            int len = Byte();
            var s = System.Text.Encoding.Latin1.GetString(D, Pos, len);
            Pos += len;
            return s;
        }
    }
}

/// <summary>One face of the built-in font pack.</summary>
internal sealed class PackFace : IGlyphSource
{
    public string Name = "";
    public int UnitsPerEm = 2048, Ascent, Descent;
    private byte[] _data = Array.Empty<byte>();
    private int[] _offsets = Array.Empty<int>();
    private int[] _advances = Array.Empty<int>();
    private PathData?[] _cache = Array.Empty<PathData?>();
    private readonly Dictionary<int, int> _cmap = new();

    public Matrix FontMatrix => Matrix.Scale(1.0 / UnitsPerEm, 1.0 / UnitsPerEm);
    public int GlyphCount => _offsets.Length;

    /// <summary>Glyph for a Unicode code point, or 0.</summary>
    public int Lookup(int unicode) => _cmap.TryGetValue(unicode, out int g) ? g : 0;

    public double Advance(int gid) => gid >= 0 && gid < _advances.Length ? _advances[gid] : -1;

    internal static PackFace Read(StandardFontPack.Reader r)
    {
        var f = new PackFace { Name = r.Str(), UnitsPerEm = r.VarInt(), Ascent = r.ZigZag(), Descent = r.ZigZag() };
        int glyphs = r.VarInt();
        int cmapCount = r.VarInt();
        int u = 0;
        for (int i = 0; i < cmapCount; i++)
        {
            u += r.VarInt();
            f._cmap[u] = r.VarInt();
        }
        f._data = r.D;
        f._offsets = new int[glyphs];
        f._advances = new int[glyphs];
        f._cache = new PathData?[glyphs];
        for (int g = 0; g < glyphs; g++)
        {
            f._advances[g] = r.VarInt();
            f._offsets[g] = r.Pos;
            // Skip the outline.
            int contours = r.VarInt();
            for (int c = 0; c < contours; c++)
            {
                int n = r.VarInt();
                r.Pos += (n + 7) / 8;
                for (int k = 0; k < 2 * n; k++) r.VarInt();
            }
        }
        return f;
    }

    public PathData? GetGlyph(int gid)
    {
        if (gid < 0 || gid >= _offsets.Length) return null;
        var cached = Volatile.Read(ref _cache[gid]);
        if (cached != null) return cached;
        var r = new StandardFontPack.Reader(_data) { Pos = _offsets[gid] };
        var path = new PathData();
        int contours = r.VarInt();
        int x = 0, y = 0;
        for (int c = 0; c < contours; c++)
        {
            int n = r.VarInt();
            var on = new bool[n];
            for (int k = 0; k < n; k++) on[k] = (r.D[r.Pos + k / 8] >> (k % 8) & 1) != 0;
            r.Pos += (n + 7) / 8;
            var xs = new int[n];
            var ys = new int[n];
            for (int k = 0; k < n; k++)
            {
                x += r.ZigZag();
                y += r.ZigZag();
                xs[k] = x;
                ys[k] = y;
            }
            TrueTypeFont.AddContour(path, xs, ys, on, 0, n - 1, Matrix.Identity);
        }
        Volatile.Write(ref _cache[gid], path);
        return path;
    }
}
